const now = new Date();
const orgUid = '9f5a0e68-7f42-4ca6-bf0d-3ed6bb0c6bf1';
const pageSize = 100;

return [{
  json: {
    workflow_name: '12_YClients_Clients_To_Clients',
    sync_started_at: now.toISOString(),
    org_uid: orgUid,
    company_id: 1647948,
    page_size: pageSize
  }
}];

const response = $input.first().json || {};
const base = $('Подготовить конфиг синхронизации').first().json || {};
const totalCount = Number(response.meta?.total_count || 0);
const totalPages = totalCount > 0 ? Math.ceil(totalCount / base.page_size) : 0;

if (totalPages === 0) {
  return [{
    json: {
      ...base,
      total_count: 0,
      total_pages: 0,
      page: 0,
      is_noop: true
    }
  }];
}

const out = [];
for (let page = 1; page <= totalPages; page += 1) {
  out.push({
    json: {
      ...base,
      total_count: totalCount,
      total_pages: totalPages,
      page,
      is_noop: false
    }
  });
}
return out;

const pageItems = $input.all();
const shared = $('Собрать очередь страниц').first().json || $('Подготовить конфиг синхронизации').first().json || {};
const seen = new Set();
const out = [];

for (const item of pageItems) {
  const rows = Array.isArray(item.json.data) ? item.json.data : [];
  for (const row of rows) {
    const clientId = Number(row?.id || 0);
    if (!Number.isFinite(clientId) || clientId <= 0) continue;
    if (seen.has(clientId)) continue;
    seen.add(clientId);
    out.push({
      json: {
        ...shared,
        client_id: clientId
      }
    });
  }
}

return out;

function normalizeTimestamp(value) {
  if (!value) return null;
  const date = new Date(String(value));
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function toDateString(value) {
  if (!value) return null;
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return null;
  return date.toISOString().slice(0, 10);
}

function cleanText(value) {
  const result = String(value ?? '').trim();
  return result || null;
}

function cleanInteger(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function cleanNumber(value, fallback = 0) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

const shared = $('Подготовить конфиг синхронизации').first().json || {};
const out = [];

for (const item of $input.all()) {
  const data = item.json?.data || {};
  const ycId = Number(data.id || 0);
  if (!Number.isFinite(ycId) || ycId <= 0) continue;

  const firstName = cleanText(data.name);
  const surname = cleanText(data.surname);
  const patronymic = cleanText(data.patronymic);
  const fullname = cleanText(
    data.display_name
      || [firstName, patronymic, surname].filter(Boolean).join(' ')
      || [firstName, surname].filter(Boolean).join(' ')
      || firstName
      || ''
  );
  if (!fullname) continue;

  const lastChangeDate = normalizeTimestamp(data.last_change_date);
  const fallbackLastVisit = toDateString(lastChangeDate) || new Date().toISOString().slice(0, 10);
  const sex = cleanText(data.sex);

  out.push({
    json: {
      org_uid: shared.org_uid,
      yc_id: String(ycId),
      yclients_id: ycId,
      fullname,
      display_name: fullname,
      name: firstName,
      surname,
      patronymic,
      phone: cleanText(data.phone),
      email: cleanText(data.email),
      birth_date: cleanText(data.birth_date),
      gender: null,
      sex,
      sex_id: cleanInteger(data.sex_id, 0),
      comment: cleanText(data.comment),
      discount: cleanNumber(data.discount, 0),
      visits: cleanInteger(data.visits, 0),
      spent: cleanNumber(data.spent, 0),
      paid: cleanNumber(data.paid, 0),
      balance: cleanNumber(data.balance, 0),
      sms_not: cleanInteger(data.sms_not, 0),
      sms_check: cleanInteger(data.sms_check, 0),
      sms_bot: cleanInteger(data.sms_bot, 0),
      importance: cleanText(data.importance),
      importance_id: cleanInteger(data.importance_id, 0),
      card: cleanText(data.card),
      categories: Array.isArray(data.categories) ? data.categories : [],
      custom_fields: data.custom_fields && typeof data.custom_fields === 'object' && !Array.isArray(data.custom_fields) ? data.custom_fields : {},
      last_change_date: lastChangeDate,
      last_visit: fallbackLastVisit
    }
  });
}

return out;

const rows = $input.all().map((item) => item.json).filter(Boolean);
const shared = $('Подготовить конфиг синхронизации').first().json || {};
return [{
  json: {
    ...shared,
    total_count: rows.length,
    synced_clients: rows.length,
    rows
  }
}];

const batch = $('Собрать upsert batch').first().json || {};
const response = $input.first().json;
const insertedOrUpdated = Array.isArray(response) ? response.length : (response ? 1 : 0);
return [{
  json: {
    ok: true,
    status: 'success',
    data: {
      org_uid: batch.org_uid,
      workflow_name: batch.workflow_name,
      total_clients: batch.total_count || 0,
      synced_clients: batch.synced_clients || 0,
      inserted_or_updated: insertedOrUpdated,
      company_id: batch.company_id,
      sync_started_at: batch.sync_started_at,
      sync_finished_at: new Date().toISOString()
    },
    errors: []
  }
}];

